import sys

def main():
    s = sys.stdin.read().split()[0]
    vowels = "aeiou"
    last = {v: -1 for v in vowels}
    start = 0
    total = 0
    for i, ch in enumerate(s):
        if ch in last:
            last[ch] = i
            lo = min(last.values())
            if lo >= start:
                total += lo - start + 1
        else:
            for v in vowels:
                last[v] = -1
            start = i + 1
    print(total)

